#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Callbacks;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.redDragonsScale)]
    public class RedDragonsScaleBuff : CurseBuffDefinition
    {
        public RedDragonsScaleBuff(string nsp, string name) : base(nsp, name)
        {
            AddTriggerFiltered(VanillaLevelCallbacks.PRE_ENTITY_TAKE_DAMAGE, PreEntityTakeDamageCallback, EntityTypes.ENEMY);
        }
        private void PreEntityTakeDamageCallback(VanillaLevelCallbacks.PreTakeDamageParams args, CallbackResult<bool> result)
        {
            var input = args.input;
            var entity = input.Entity;
            if (!entity.Level.HasBuff(this))
                return;
            if (!entity.IsHostileEntity())
                return;
            if (input.HasEffect(VanillaDamageEffects.EXPLOSION) || input.HasEffect(VanillaDamageEffects.FIRE))
            {
                input.Multiply(0.6f);
            }
        }
    }
}
